BEGIN;
CREATE SCHEMA IF NOT EXISTS ged;
CREATE TABLE IF NOT EXISTS ged.slo_definition (id uuid PRIMARY KEY, code varchar(100) UNIQUE NOT NULL, name varchar(200) NOT NULL, description text, service varchar(100) NOT NULL, indicator_type varchar(40) NOT NULL, target_percentage numeric(7,4) NOT NULL CHECK(target_percentage BETWEEN 0 AND 100), window_type varchar(30) NOT NULL, window_days integer NOT NULL CHECK(window_days > 0), latency_threshold_ms integer, enabled boolean NOT NULL DEFAULT true, severity varchar(4) NOT NULL, owner_team varchar(100), runbook_code varchar(100), approval_status varchar(20) NOT NULL DEFAULT 'PROPOSED', created_at_utc timestamptz NOT NULL DEFAULT now(), updated_at_utc timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ged.slo_measurement (id bigserial PRIMARY KEY, slo_id uuid NOT NULL REFERENCES ged.slo_definition(id), window_start_utc timestamptz NOT NULL, window_end_utc timestamptz NOT NULL, valid_events bigint NOT NULL, good_events bigint NOT NULL, value_percentage numeric(9,5), created_at_utc timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ged.slo_error_budget (id bigserial PRIMARY KEY, slo_id uuid NOT NULL REFERENCES ged.slo_definition(id), window_start_utc timestamptz NOT NULL, window_end_utc timestamptz NOT NULL, total_budget numeric NOT NULL, consumed_budget numeric NOT NULL, remaining_budget numeric NOT NULL, burn_rate numeric NOT NULL, status varchar(30) NOT NULL);
CREATE TABLE IF NOT EXISTS ged.operational_incident (id uuid PRIMARY KEY, incident_number varchar(40) UNIQUE NOT NULL, title varchar(250) NOT NULL, description text, severity varchar(4) NOT NULL, status varchar(30) NOT NULL, service varchar(100) NOT NULL, slo_code varchar(100), alert_code varchar(100), cluster_id varchar(100), node_id varchar(100), deployment_id varchar(100), detected_at_utc timestamptz NOT NULL, acknowledged_at_utc timestamptz, resolved_at_utc timestamptz, closed_at_utc timestamptz, owner varchar(100), correlation_id uuid, summary_json jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS ged.operational_incident_event (id bigserial PRIMARY KEY, incident_id uuid NOT NULL REFERENCES ged.operational_incident(id), event_type varchar(60) NOT NULL, note text, actor_id varchar(100), created_at_utc timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ged.operational_alert (id uuid PRIMARY KEY, code varchar(100) NOT NULL, service varchar(100) NOT NULL, cluster_id varchar(100), environment varchar(50) NOT NULL, deduplication_key varchar(420) NOT NULL, status varchar(30) NOT NULL, first_seen_at_utc timestamptz NOT NULL, last_seen_at_utc timestamptz NOT NULL, occurrence_count integer NOT NULL DEFAULT 1, UNIQUE(deduplication_key));
CREATE TABLE IF NOT EXISTS ged.operational_alert_notification (id bigserial PRIMARY KEY, alert_id uuid NOT NULL REFERENCES ged.operational_alert(id), sink varchar(50) NOT NULL, result varchar(30) NOT NULL, sent_at_utc timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS ged.operational_silence (id uuid PRIMARY KEY, alert_code varchar(100), service varchar(100), cluster_id varchar(100), environment varchar(50), starts_at_utc timestamptz NOT NULL, expires_at_utc timestamptz NOT NULL, reason text NOT NULL, actor_id varchar(100) NOT NULL, CHECK(expires_at_utc > starts_at_utc));
CREATE TABLE IF NOT EXISTS ged.observability_deployment_marker (id uuid PRIMARY KEY, deployment_id varchar(100) NOT NULL, release varchar(100), version varchar(50), commit_sha varchar(64), source_color varchar(20), target_color varchar(20), status varchar(30) NOT NULL, recorded_at_utc timestamptz NOT NULL);
COMMIT;
